update public.translations
set data = jsonb_set(
             jsonb_set(data, '{parcours,items}', '[{"y": "2016 — Aujourd''hui", "r": "Directrice de Production & Co-fondatrice", "c": "Super Motion", "d": "Pilotage de projets photo et vidéo de A à Z : conception, DA, devis, planning, repérage, casting, tournage, shooting, post-production, livraison. Campagnes 360, direction d''une équipe de 3 à 15 personnes, décisionnaire opérationnelle et budgétaire. BETC, Publicis, BBDO, TBWA, Romance, TAG Heuer, Vacheron Constantin, La Redoute, Asics, Krys Group, Avène, Kinder, Samsung, Fiat, Unesco."}, {"y": "2014 — 2016", "r": "Directrice des opérations & du trafic création", "c": "Geometry — WPP", "d": "Pilotage des opérations et coordination de projets digitaux et print, 15 créatifs internes et partenaires externes, contrôle budgétaire et reporting client. Piaget, Vogue, Croix Rouge, Coca-Cola, Nestlé, Alcatel."}, {"y": "2009 — 2014", "r": "Responsable achat d''art & production créative", "c": "Razorfish (ex Digitas)", "d": "Production vidéo de bout en bout, trafic création et production digitale pour 70 profils internes et freelances, achat d''art et négociation des droits. Hermès, Lancôme, Armani, Hennessy, Dassault, La Poste, Nissan, Renault."}, {"y": "2008 — 2009", "r": "Responsable trafic & achat d''art", "c": "Ailleurs Exactement", "d": "Coordination de productions, organisation de shootings et gestion des talents."}, {"y": "2007 — 2008", "r": "Responsable trafic création", "c": "TBWA", "d": "Pilotage du trafic création pour 40 créatifs internes : plannings, priorités et livraisons. Sourcing de prestataires, négociation des tarifs et gestion des droits."}]'::jsonb),
             '{cv,exp}', '[{"r": "Directrice de Production & Co-fondatrice", "c": "Super Motion", "y": "2016 — Aujourd''hui", "pts": ["Pilotage de projets photo et vidéo de A à Z : brief, kick-off, PPM, conception, DA, devis, planning, repérage, casting, tournage, shooting, post-production, livraison.", "Campagne 360 : adaptation des contenus pour tous les points de contact (digital, social media, print, retail, campagnes internationales).", "Direction de tournage : repérages, castings, constitution de l''équipe technique et créative, logistique, plan de travail et coordination plateau.", "Direction de shooting : brief créatif, sélection des talents (photographe, styliste, maquilleur), casting et coordination plateau.", "Gestion complète de la post-production : montage, étalonnage, motion design, 3D, IA, sound design, VFX, voix off, retouches photos.", "Process et outils de cadrage : méthodologie, brief de production, shooting objectives.", "Direction d''une équipe interne et mobilisation de talents externes : 3 à 15 personnes par production en moyenne.", "Décisionnaire opérationnelle et budgétaire : choix des prestataires, validation des devis et dépenses, rentabilité, reporting financier.", "Veille créative : tendances visuelles, nouveaux talents, outils IA.", "Négociation : droits d''image, contrats comédiens et mannequins."], "clients": "BETC, Publicis, BBDO, TBWA, Romance, TAG Heuer, Vacheron Constantin, La Redoute, Asics, Krys Group, Avène, Kinder, Samsung, Fiat, Unesco"}, {"r": "Directrice des opérations & du trafic création", "c": "Geometry (WPP)", "y": "Avr. 2014 — Janv. 2016", "pts": ["Pilotage des opérations et coordination de projets digitaux et print : gestion des priorités, optimisation des process, plannings et suivi quotidien.", "Gestion des ressources : coordination de 15 créatifs internes et partenaires externes.", "Gestion financière : reporting client, contrôle budgétaire, gestion des dépenses externes et optimisation de la productivité.", "Gestion des prestataires : sourcing, négociation tarifs et gestion des droits."], "clients": "Piaget, Vogue, Croix Rouge, Coca-Cola, Nestlé, Alcatel"}, {"r": "Responsable achat d''art & production créative", "c": "Razorfish (ex Digitas)", "y": "Déc. 2009 — Avr. 2014", "pts": ["Production vidéo : brief et sélection des sociétés de production, gestion des budgets et plannings, PPM, suivi de production et coordination des équipes.", "Pilotage du trafic création et coordination de production digitale : gestion des plannings, des priorités et des livraisons pour 70 profils internes et freelances.", "Achat d''art : sourcing de talents, gestion des banques d''images et négociation des droits.", "Gestion opérationnelle et financière : optimisation des process et outils, estimation des charges de production, analyse et prévision des dépenses créatives.", "Recrutement : sélection et intégration de profils créatifs internes."], "clients": "Hermès, Lancôme, Armani, Hennessy, Dassault, La Poste, Nissan, Renault"}, {"r": "Responsable trafic & achat d''art", "c": "Ailleurs Exactement", "y": "Nov. 2008 — Avr. 2009", "pts": ["Coordination de productions, organisation de shootings et gestion des talents."], "clients": ""}, {"r": "Responsable trafic création", "c": "TBWA", "y": "Janv. 2007 — Oct. 2008", "pts": ["Pilotage du trafic création : gestion des plannings, des priorités et des livraisons pour 40 créatifs internes.", "Gestion des prestataires : sourcing, négociation tarifs et gestion des droits."], "clients": ""}]'::jsonb),
    updated_at = now()
where lang = 'fr';

